+];
+const keys={},tile=40,MW=31,MH=23;let world=[],rooms=[],heroes=[],enemies=[],particles=[],projectiles=[],decals=[],floor=1,kills=0,cleared=0,souls=3,runStart=Date.now(),ai=true,gameState='select',attackTimer=0,skillTimer=0,shake=0,frames=0,entered=false,selected=[],relics=[],logEntries=[];
+let cell={w:800,h:600,scale:1,ox:0,oy:0};
+function log(text){logEntries.unshift(text);logEntries=logEntries.slice(0,5);document.getElementById('journal').innerHTML=logEntries.map(t=>`<div class="log-line"><i>✦</i><span>${t}</span></div>`).join('')}
+const rand=(a,b)=>Math.random()*(b-a)+a,ri=(a,b)=>Math.floor(rand(a,b+1),),choose=a=>a[Math.floor(Math.random()*a.length)],clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
+function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));cell.w=canvas.width;cell.h=canvas.height;cell.scale=d;}
+new ResizeObserver(resize).observe(canvas);window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'&&gameState==='playing')document.getElementById('aiToggle').click()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+function renderClassSelect(){const grid=document.getElementById('classGrid');grid.innerHTML='';classes.forEach((c,i)=>{const b=document.createElement('button');b.className='class-card';b.innerHTML=`<div class="emoji">${c.emoji}</div><strong style="color:${c.color}">${c.name}</strong><small>${c.desc}</small>`;b.onclick=()=>pickClass(i);grid.appendChild(b)});selected=[];updatePick()}
+function pickClass(i){if(selected.length>=3)return;if(selected.includes(i)){document.getElementById('pickNote').textContent='Each delver needs a different class.';return}selected.push(i);document.querySelectorAll('.class-card').forEach((el,j)=>{el.classList.toggle('selected',selected.includes(j));if(selected.includes(j))el.style.boxShadow=`inset 0 -2px ${classes[j].color}`});updatePick()}
+function updatePick(){const n=selected.length;document.getElementById('slotLabel').textContent=n<3?`PLAYER ${n+1} — CHOOSE A CLASS`:'PARTY READY — THREE DELVERS';document.getElementById('pickNote').textContent=n<3?`${n} of 3 chosen · choose different classes.`:'Choose Begin Descent to enter the dungeon.';document.getElementById('startBtn').disabled=n!==3}
+document.getElementById('startBtn').onclick=()=>{heroes=selected.map((ci,id)=>{let c=classes[ci];return {id,class:c,x:0,y:0,hp:c.hp,maxHp:c.hp,damage:c.damage,speed:c.speed,attack:0,skill:0,invuln:0,faceX:1,faceY:0,dead:false,boost:0}});document.getElementById('classVeil').classList.remove('show');floor=1;kills=0;cleared=0;souls=3;relics=[];runStart=Date.now();logEntries=[];log('Three delvers enter the deep.');newFloor()};
+document.getElementById('aiToggle').onclick=()=>{ai=!ai;document.getElementById('aiToggle').textContent=`COMPANION AI: ${ai?'ON':'OFF'}`;log(ai?'Companion AI engaged.':'Manual co-op controls engaged.')};
+document.getElementById('retryBtn').onclick=()=>{document.getElementById('overVeil').classList.remove('show');renderClassSelect();document.getElementById('classVeil').classList.add('show');gameState='select'};
+function makeMap(){world=Array.from({length:MH},()=>Array(MW).fill(0));rooms=[];let attempts=0;while(rooms.length<7&&attempts++<200){let w=ri(4,7),h=ri(4,6),x=ri(1,MW-w-2),y=ri(1,MH-h-2);if(rooms.every(r=>x+w+1<r.x||r.x+r.w+1<x||y+h+1<r.y||r.y+r.h+1<y)){rooms.push({x,y,w,h,cx:x+w/2,cy:y+h/2})}}
+rooms.sort((a,b)=>a.cx-b.cx);rooms.forEach(r=>{for(let y=r.y;y<r.y+r.h;y++)for(let x=r.x;x<r.x+r.w;x++)world[y][x]=1});for(let i=1;i<rooms.length;i++){let a=rooms[i-1],b=rooms[i],x=Math.round(a.cx),y=Math.round(a.cy),ex=Math.round(b.cx),ey=Math.round(b.cy);while(x!==ex){world[y][x]=1;x+=Math.sign(ex-x)}while(y!==ey){world[y][x]=1;y+=Math.sign(ey-y)}world[y][x]=1}
+let start=rooms[0];heroes.forEach((h,i)=>{h.x=(start.cx+(i-1)*.7)*tile;h.y=start.cy*tile;h.dead=false;h.hp=h.maxHp});let roomCount=rooms.length,base=4+floor*2;enemies=[];for(let i=0;i<base;i++){let r=rooms[ri(1,roomCount-1)],type=choose(['crawler','crawler','spitter','brute']);enemies.push({type,x:rand(r.x+1,r.x+r.w-1)*tile,y:rand(r.y+1,r.y+r.h-1)*tile,hp:(type==='brute'?70: type==='spitter'?40:34)+floor*6,maxHp:(type==='brute'?70: type==='spitter'?40:34)+floor*6,speed:(type==='brute'?0.75:type==='spitter'?0.85:1.05)+Math.min(floor*.025,.25),damage:5+floor*1.35,cd:rand(0,60),hit:0,phase:rand(0,6.2),dead:false})}particles=[];projectiles=[];decals=[];document.getElementById('enemyCount').textContent=enemies.length;document.getElementById('chipFloor').textContent=String(floor).padStart(2,'0');document.getElementById('floorNo').textContent=String(floor).padStart(2,'0');document.getElementById('floorName').textContent=choose(['Mosslight Warrens','The Drowned Archive','Cinderdeep','Hollowroot Crypt','Gloamstone Vault','The Forgotten Foundry','Moonless Catacombs','Ashen Reliquary']);document.getElementById('threat').textContent=floor<3?'LOW':floor<6?'RISING':'SEVERE';document.getElementById('roomLabel').textContent='SCOUTING';document.getElementById('objectiveCount').textContent=`0 / ${enemies.length}`;document.getElementById('floorProgress').style.width='0%';gameState='playing';log(`Floor ${floor}: ${enemies.length} creatures stir in the dark.`);updateParty()}
+function newFloor(){makeMap()}
+function walkable(x,y){let tx=Math.floor(x/tile),ty=Math.floor(y/tile);return tx>=0&&ty>=0&&tx<MW&&ty<MH&&world[ty][tx]===1}
+function moveEntity(e,dx,dy){if(!dx&&!dy)return;const nx=e.x+dx,ny=e.y+dy,r=11;if(walkable(nx-r,e.y-r)&&walkable(nx+r,e.y-r)&&walkable(nx-r,e.y+r)&&walkable(nx+r,e.y+r))e.x=nx;if(walkable(e.x-r,ny-r)&&walkable(e.x+r,ny-r)&&walkable(e.x-r,ny+r)&&walkable(e.x+r,ny+r))e.y=ny}
+function nearestEnemy(x,y){let best=null,d=Infinity;for(let e of enemies)if(!e.dead){let v=Math.hypot(e.x-x,e.y-y);if(v<d){best=e;d=v}}return best}
+function damageEnemy(e,n,color='#f5cb83'){if(!e||e.dead)return;e.hp-=n;e.hit=9;for(let i=0;i<5;i++)particles.push({x:e.x,y:e.y,vx:rand(-2,2),vy:rand(-2,2),life:rand(12,24),color,size:rand(2,4)});if(e.hp<=0){e.dead=true;kills++;for(let i=0;i<12;i++)particles.push({x:e.x,y:e.y,vx:rand(-2.7,2.7),vy:rand(-2.7,2.7),life:rand(20,40),color:'#e7ae68',size:rand(2,5)});document.getElementById('statKills').textContent=kills;log(choose(['A shadow unmade.','The path grows quieter.','Another threat put to rest.']))}}
+function attack(h){if(h.dead||h.attack>0)return;h.attack=22;let e=nearestEnemy(h.x,h.y);if(!e)return;let dx=e.x-h.x,dy=e.y-h.y,d=Math.hypot(dx,dy)||1;h.faceX=dx/d;h.faceY=dy/d;let ranged=['Arcanist','Ranger','Stormcaller'].includes(h.class.name),reach=ranged?255:74;if(d>reach)return;if(ranged){projectiles.push({x:h.x+h.faceX*13,y:h.y+h.faceY*13,vx:h.faceX*6,vy:h.faceY*6,life:42,damage:h.damage,color:h.class.color,radius:5,pierce:h.class.name==='Arcanist'?1:0})}else{for(let q of enemies)if(!q.dead&&Math.hypot(q.x-h.x,q.y-h.y)<(h.class.name==='Vanguard'?82:58)){let dot=((q.x-h.x)*h.faceX+(q.y-h.y)*h.faceY)/Math.max(1,Math.hypot(q.x-h.x,q.y-h.y));if(dot>.1)damageEnemy(q,h.damage,h.class.color)}}}
+function useSkill(h){if(h.dead||h.skill>0)return;h.skill=300;const k=h.class.kind;let targets=enemies.filter(e=>!e.dead).sort((a,b)=>Math.hypot(a.x-h.x,a.y-h.y)-Math.hypot(b.x-h.x,b.y-h.y));if(k==='heal'){heroes.forEach(a=>{a.hp=Math.min(a.maxHp,a.hp+35);particles.push({x:a.x,y:a.y,life:28,color:'#a6ce95',size:8,vx:rand(-.5,.5),vy:-1})});log('Verdant Bloom restores the party.')}else if(k==='volley'){targets.slice(0,5).forEach(e=>damageEnemy(e,h.damage*1.8,h.class.color));log('A storm of arrows rains down.')}else if(k==='chain'){let hit=targets.slice(0,4);hit.forEach((e,i)=>{damageEnemy(e,h.damage*2.1,h.class.color);if(i<hit.length-1)particles.push({x:e.x,y:e.y,vx:0,vy:0,life:15,color:'#8eb7e8',size:16})});log('Lightning leaps between foes.')}else if(k==='blink'){let e=targets[0];if(e){h.x=e.x-30;h.y=e.y;targets.filter(q=>Math.hypot(q.x-h.x,q.y-h.y)<100).forEach(q=>damageEnemy(q,h.damage*2.6,h.class.color))}log('The Shade vanishes into darkness.')}else if(k==='rage'){h.boost=240;for(let i=0;i<14;i++)particles.push({x:h.x,y:h.y,vx:rand(-2,2),vy:rand(-2,2),life:25,color:'#df825b',size:4});log('Berserker enters a blood-fueled rage.')}else{let radius=k==='nova'?195:k==='spin'?118:125;for(let e of targets)if(Math.hypot(e.x-h.x,e.y-h.y)<radius)damageEnemy(e,h.damage*(k==='slam'?2.4:k==='nova'?2.2:1.7),h.class.color);for(let i=0;i<32;i++){let a=Math.PI*2*i/32;particles.push({x:h.x+Math.cos(a)*25,y:h.y+Math.sin(a)*25,vx:Math.cos(a)*2,vy:Math.sin(a)*2,life:22,color:h.class.color,size:4})}log(`${h.class.skill} crashes through the chamber.`)}shake=8}
+function triggerGameOver(){gameState='over';document.getElementById('overTitle').textContent=`Fallen on floor ${floor}`;document.getElementById('overText').textContent=`Your party cleared ${cleared} ${cleared===1?'floor':'floors'} and defeated ${kills} foes. Every run ends somewhere — this one ends here.`;document.getElementById('overVeil').classList.add('show')}
+function partyDamage(h,damage){if(h.dead||h.invuln>0)return;h.hp-=damage;h.invuln=52;shake=3;for(let i=0;i<7;i++)particles.push({x:h.x,y:h.y,vx:rand(-2,2),vy:rand(-2,2),life:20,color:'#e8675b',size:3});if(h.hp<=0){souls--;document.getElementById('soulCount').textContent='♥ '.repeat(Math.max(0,souls)).trim()||'—';if(souls<=0){triggerGameOver();return}h.hp=h.maxHp;h.x=rooms[0].cx*tile;h.y=rooms[0].cy*tile;h.invuln=160;log(`${h.class.name} falls, then rises. ${souls} shared soul${souls===1?'':'s'} remain.`)}updateParty()}
+function floorCleared(){if(gameState!=='playing')return;gameState='reward';cleared++;document.getElementById('roomLabel').textContent='CLEARED';document.getElementById('objectiveTitle').textContent='Chamber cleared';document.getElementById('objectiveDesc').textContent='Choose a boon before descending deeper.';document.getElementById('objectiveCount').textContent='SAFE';document.getElementById('floorProgress').style.width='100%';document.getElementById('statFloors').textContent=cleared;document.getElementById('rewardSub').textContent=`Floor ${floor} secured. Choose one party-wide reward from these three randomized offerings.`;makeRewards();document.getElementById('rewardVeil').classList.add('show');log(`Floor ${floor} cleared. The relic chest opens.`)}

