function floorCleared(){if(gameState!=='playing')return;gameState='reward';cleared++;document.getElementById('roomLabel').textContent='CLEARED';document.getElementById('objectiveTitle').textContent='Chamber cleared';document.getElementById('objectiveDesc').textContent='Choose a boon before descending deeper.';document.getElementById('objectiveCount').textContent='SAFE';document.getElementById('floorProgress').style.width='100%';document.getElementById('statFloors').textContent=cleared;document.getElementById('rewardSub').textContent=`Floor ${floor} secured. Choose one party-wide reward from these three randomized offerings.`;makeRewards();document.getElementById('rewardVeil').classList.add('show');log(`Floor ${floor} cleared. The relic chest opens.`)}
const rewardPool=[
 {name:'Sunforged Edge',icon:'⚔️',rarity:'WEAPON · RARE',desc:'+18% damage for every delver.',apply(){heroes.forEach(h=>h.damage*=1.18)}},
 {name:'Tallowheart Charm',icon:'🧿',rarity:'RELIC · UNCOMMON',desc:'+22 max health and restore the party.',apply(){heroes.forEach(h=>{h.maxHp+=22;h.hp=Math.min(h.maxHp,h.hp+35)})}},
 {name:'Fleetfoot Greaves',icon:'🥾',rarity:'EQUIPMENT · UNCOMMON',desc:'The party moves 12% faster.',apply(){heroes.forEach(h=>h.speed*=1.12)}},
 {name:'Bloodglass Ring',icon:'💍',rarity:'RELIC · RARE',desc+'Heal 3 health after each strike.',apply(){heroes.forEach(h=>h.lifeSteal=(h.lifeSteal||0)+3)}},
 {name:'Moonwell Phial',icon:'🌙',rarity:'CONSUMABLE · RARE',desc:'Restore 45 health to all delvers.',apply(){heroes.forEach(h=>h.hp=Math.min(h.maxHp,h.hp+45))}},
 {name:'Quickening Sigil',icon:'⏳',rarity:'RELIC · EPIC',desc:'Skills recharge 20% faster.',apply(){heroes.forEach(h=>h.skillRate=(h.skillRate||1)*.8)}},
 {name:'Ashen Mantle',icon:'🔥',rarity:'ARMOR · RARE',desc:'Reduce incoming damage by 20%.',apply(){heroes.forEach(h=>h.armor=(h.armor||0)+.2)}},
 {name:'Glass Cannon',icon:'💠',rarity:'WEAPON · EPIC',desc:'+35% damage, but enemies hit harder.',apply(){heroes.forEach(h=>h.damage*=1.35);enemies.forEach(e=>e.damage*=1.25)}},
 {name:'Soul Lantern',icon:'🕯️',rarity:'RELIC · LEGENDARY',desc:'Gain one shared soul (up to 5).',apply(){souls=Math.min(5,souls+1);document.getElementById('soulCount').textContent='♥ '.repeat(souls).trim()}},
 {name:'Guardian Knot',icon:'🪢',rarity:'ARMOR · UNCOMMON',desc:'Restore 12 health after each room.',apply(){heroes.forEach(h=>h.hp=Math.min(h.maxHp,h.hp+12))}},
 {name:'Echoing Rune',icon:'✨',rarity:'RELIC · EPIC',desc:'+25% damage, skills recharge faster.',apply(){heroes.forEach(h=>{h.damage*=1.25;h.skillRate=(h.skillRate||1)*.88})}},
 {name:'Dawnseed',icon:'🌱',rarity:'RELIC · RARE',desc:'+15 max health and +8% movement speed.',apply(){heroes.forEach(h=>{h.maxHp+=15;h.hp+=15;h.speed*=1.08})}}
].map(x=>({...x,desc:x.desc}));
function makeRewards(){let pool=[...rewardPool].sort(()=>Math.random()-.5).slice(0,3);let grid=document.getElementById('rewardGrid');grid.innerHTML='';pool.forEach(r=>{let b=document.createElement('button');b.className='reward';b.innerHTML=`<div class="reward-icon">${r.icon}</div><div class="rarity">${r.rarity}</div><h3>${r.name}</h3><p>${r.desc}</p>`;b.onclick=()=>{r.apply();relics.push(r.name);updateRelics();document.getElementById('rewardVeil').classList.remove('show');floor++;heroes.forEach(h=>{h.hp=Math.min(h.maxHp,h.hp+12)});document.getElementById('objectiveTitle').textContent='Clear the chamber';document.getElementById('objectiveDesc').textContent='Defeat every creature to find the exit.';document.getElementById('statPower').textContent=(heroes.reduce((a,h)=>a+h.damage,0)/(selected.reduce((a,i)=>a+classes[i].damage,0))).toFixed(1)+'×';log(`Party claimed ${r.name}.`);newFloor()};grid.appendChild(b)})}
function updateRelics(){document.getElementById('relicCount').textContent=`${relics.length} FOUND`;document.getElementById('itemList').innerHTML=relics.length?relics.map(n=>`<span class="item-chip">✦ ${n}</span>`).join(''):'<span style="color:#777;font-size:10px">No relics yet. Earn your first after floor one.</span>'}
