function draw(){const W=canvas.width,H=canvas.height;if(!W||!H)return;ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#171816';ctx.fillRect(0,0,W,H);const alive=heroes.filter(h=>!h.dead),cx=alive.length?alive.reduce((a,h)=>a+h.x,0)/alive.length:MW*tile/2,cy=alive.length?alive.reduce((a,h)=>a+h.y,0)/alive.length:MH*tile/2;const shakeX=shake?rand(-shake,shake):0,shakeY=shake?rand(-shake,shake):0,ox=W/2-cx+shakeX,oy=H/2-cy+shakeY;ctx.save();ctx.translate(ox,oy);
